#include "apps.h"
#include "app_stage_e.h"
#include "heap.h"
#include "vfs.h"
#include "audio.h"
#include "keyboard.h"
#include "timer.h"
#include "fat32.h"
#define RES_MAX 12
typedef struct{char path[64],name[40];uint32_t size;}track_t;
typedef struct{track_t tr[RES_MAX];int count,selected;bool playing;uint8_t volume;char status[48];uint64_t started;}res_t;
static bool ends_wav(const char*s){int n=se_len(s);return n>4&&s[n-4]=='.'&&(s[n-3]=='w'||s[n-3]=='W')&&(s[n-2]=='a'||s[n-2]=='A')&&(s[n-1]=='v'||s[n-1]=='V');}
static void res_scan(res_t*s){s->count=0;for(int i=0;i<vfs_count()&&s->count<RES_MAX;i++){vfs_node_t*n=vfs_at(i);if(n&&ends_wav(n->name)){se_copy(s->tr[s->count].path,n->name,64);se_copy(s->tr[s->count].name,n->name,40);s->tr[s->count].size=(uint32_t)n->size;s->count++;}}if(!s->count){se_copy(s->tr[0].path,"/startup.wav",64);se_copy(s->tr[0].name,"Cold Start - startup.wav",40);s->tr[0].size=0;s->count=1;}if(s->selected>=s->count)s->selected=0;
 if(fat32_is_mounted()){char idx[768];int p=0;fat32_mkdir_p("/disk/Sanctum/system");for(int i=0;i<s->count;i++){for(int k=0;s->tr[i].path[k]&&p<750;k++)idx[p++]=s->tr[i].path[k];idx[p++]='\n';}fat32_save_file("/disk/Sanctum/system/audio-library.idx",idx,p);}
}
static void res_play(res_t*s){if(s->playing){audio_stop();s->playing=false;se_copy(s->status,"paused",48);return;}audio_set_volume(s->volume);if(audio_play_wav(s->tr[s->selected].path)){s->playing=true;s->started=timer_get_uptime_ms();se_copy(s->status,"playing PCM through AC97",48);}else se_copy(s->status,audio_is_ready()?"WAV unavailable":"No audio device - visual mode",48);}
static void res_draw(window_t*w,const gfx_target_t*t){res_t*s=w->user_data;gfx_clear(t,UI_DARK_CANVAS);se_header(t,"RESONANCE - SOUND PRISM",s->count?s->tr[s->selected].name:"No sound strata",true);se_text(t,78,102,"Prism Choir - Ignition EP - 2026",0xFFA99FAA);int cx=360,cy=378;ui_draw_ring(t,cx,cy,150,5,(uint8_t)((timer_get_uptime_ms()/25)%255),0xFF403744,UI_ACCENT_ORANGE);gfx_fill_round_rect(t,cx-96,cy-96,192,192,96,0xFF29222D);ui_draw_bitmap_scaled(t,cx-36,cy-36,72,72,ui_logo_big());for(int i=0;i<48;i++){int h=18+(int)((i*37+timer_get_uptime_ms()/23)%94);uint32_t c=ui_sunset((uint8_t)(i*5));gfx_fill_rect(t,78+i*15,690-h,8,h,c);}se_text(t,78,706,"1:42",0xFFA99FAA);se_text(t,380,706,s->playing?"SPATIAL - PLAYING":"SPATIAL - PAUSED",0xFFA99FAA);int x=888,y=108;se_text(t,x,82,"QUEUE - WARM",0xFFA99FAA);for(int i=0;i<s->count&&i<5;i++){se_card(t,x,y,w->width-x-70,68,0xFF211923,i==s->selected?UI_ACCENT_CORAL:0xFF352A36);ui_draw_bitmap_scaled(t,x+18,y+18,32,32,ui_icon(UI_ICON_MUSIC));se_bold(t,x+68,y+16,s->tr[i].name,UI_DARK_TEXT);se_text(t,x+68,y+40,i==s->selected?"selected - Enter toggles":"WAV / PCM",0xFFA99FAA);y+=82;}se_card(t,x,y+20,w->width-x-70,122,0xFF211923,0xFF352A36);se_text(t,x+24,y+44,"OUTPUT",0xFFA99FAA);se_text(t,x+24,y+72,audio_is_ready()?"AC97 - 48 kHz stereo":"No device - spectrum only",UI_DARK_TEXT);se_progress(t,x+24,y+104,w->width-x-118,s->volume*255/100,0xFF403744,UI_ACCENT_MAGENTA);se_text(t,78,w->height-34,s->status,UI_ACCENT_CORAL);}
static void res_key(window_t*w,char c){res_t*s=w->user_data;if(c==27){audio_stop();se_close(w);return;}if(c==KBD_KEY_UP)s->selected=(s->selected+s->count-1)%s->count;else if(c==KBD_KEY_DOWN||c=='\t')s->selected=(s->selected+1)%s->count;else if(c=='\n'||c==' ')res_play(s);else if((c=='+'||c=='=')&&s->volume<100){s->volume+=5;audio_set_volume(s->volume);}else if(c=='-'&&s->volume>5){s->volume-=5;audio_set_volume(s->volume);}else if(c=='r'||c=='R'){res_scan(s);se_copy(s->status,"library rescanned",48);}}
static void res_click(window_t*w,int x,int y){res_t*s=w->user_data;if(x>=888&&y>=108){int i=(y-108)/82;if(i>=0&&i<s->count){s->selected=i;res_play(s);}}else if(x>=210&&x<=510&&y>=228&&y<=528)res_play(s);}
window_t* app_resonance_open(void){res_t*s=kmalloc(sizeof(*s));if(!s)return 0;s->selected=0;s->playing=false;s->volume=72;s->started=0;res_scan(s);se_copy(s->status,audio_is_ready()?"Enter play  +/- volume  R rescan":"No audio device - visual fallback",48);window_t*w=se_workspace("Resonance",res_draw,res_click,res_key,s,true);if(w)w->wants_continuous_redraw=true;else kfree(s);return w;}
